import{c as e,Q as s,j as d,m as c}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"稽核：.claude/agents · .claude/hooks · settings.json · .claude/commands","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-07-03-harness-audit-appendix/inv-agents-hooks.md","filePath":"research/reports/2026-07-03-harness-audit-appendix/inv-agents-hooks.md","lastUpdated":1785909234000}'),t={name:"research/reports/2026-07-03-harness-audit-appendix/inv-agents-hooks.md"};function a(r,o,n,i,l,m){return s(),d("div",null,[...o[0]||(o[0]=[c('<h1 id="稽核-claude-agents-·-claude-hooks-·-settings-json-·-claude-commands" tabindex="-1">稽核：.claude/agents · .claude/hooks · settings.json · .claude/commands <a class="header-anchor" href="#稽核-claude-agents-·-claude-hooks-·-settings-json-·-claude-commands" aria-label="Permalink to &quot;稽核：.claude/agents · .claude/hooks · settings.json · .claude/commands&quot;">​</a></h1><h2 id="_1-agents-frontmatter-一致性-13-檔-非題述-14-index-md-明寫「共-13-個」與實檔一致" tabindex="-1">1. Agents frontmatter 一致性（13 檔，非題述 14；INDEX.md 明寫「共 13 個」與實檔一致） <a class="header-anchor" href="#_1-agents-frontmatter-一致性-13-檔-非題述-14-index-md-明寫「共-13-個」與實檔一致" aria-label="Permalink to &quot;1. Agents frontmatter 一致性（13 檔，非題述 14；INDEX.md 明寫「共 13 個」與實檔一致）&quot;">​</a></h2><ul><li>全部 13 檔 <code>model:</code> 欄位一律用 alias（<code>haiku</code>/<code>sonnet</code>/<code>opus</code>），<strong>無任何寫死版本 id</strong>（如 <code>claude-3-5-sonnet-20241022</code>）— 乾淨。 <ul><li>對照：<code>.claude/settings.json:4</code> <code>&quot;model&quot;: &quot;claude-sonnet-4-6&quot;</code> 是<strong>具體版本 id</strong>（非 alias），與 agents 慣例不同調——非錯誤但值得注意：settings.json 頂層 model 綁死版本號，模型世代升級時需手動改此檔（agents 用 alias 則由 harness 自動解析新版本）。</li></ul></li><li>description 內 &quot;Do NOT use for&quot; 交叉引用檢查：<code>researcher.md</code> ↔ <code>quick-code-reviewer.md</code> ↔ <code>reviewer.md</code> ↔ <code>security-reviewer.md</code> ↔ <code>security-auditor.md</code> ↔ <code>test-writer.md</code> ↔ <code>doc-writer.md</code> ↔ <code>implementer.md</code> ↔ <code>haiku-implementer.md</code> ↔ <code>multi-mode-agent.md</code> 全部形成雙向排斥描述，一致。</li><li><code>.claude/agents/INDEX.md</code> 速查表 13 列與實際 13 檔一一對應，用途/model/禁止欄位與各檔 frontmatter description 相符，未見過時或矛盾條目。</li></ul><h3 id="agent-×-skill-職責重疊-同觸發詞兩邊搶" tabindex="-1">Agent × Skill 職責重疊（同觸發詞兩邊搶） <a class="header-anchor" href="#agent-×-skill-職責重疊-同觸發詞兩邊搶" aria-label="Permalink to &quot;Agent × Skill 職責重疊（同觸發詞兩邊搶）&quot;">​</a></h3><ul><li><strong>無明顯字面重疊</strong>：agents 觸發詞多為中文動詞句（「幫我實作」「做安全審查」），skills 觸發詞為 <code>/slash-command</code> 或英文 keyword（<code>harness-meta:audit</code> 等），命名空間分離。</li><li>唯一交界案例：<code>memory-compactor</code>——<code>.claude/agents/memory-compactor.md</code>（實際壓縮執行者）+ <code>.claude/commands/memory-compactor.md</code>（orchestration wrapper，呼叫 agent）。<strong>非重複，是設計上的 command→agent 轉發</strong>（command 負責行數檢查+驗證+commit，agent 負責純壓縮邏輯）。</li><li><code>dreaming-consolidator</code> skill、<code>pilot-review</code> skill、<code>handoff</code> skill、<code>harness-meta</code> skill 皆在文件中「提及」memory-compactor（作為委派對象），非各自重複實作同功能——屬正常交叉引用。</li></ul><h2 id="_2-hooks-佈線驗證-settings-json-↔-claude-hooks-sh" tabindex="-1">2. Hooks 佈線驗證（settings.json ↔ .claude/hooks/*.sh） <a class="header-anchor" href="#_2-hooks-佈線驗證-settings-json-↔-claude-hooks-sh" aria-label="Permalink to &quot;2. Hooks 佈線驗證（settings.json ↔ .claude/hooks/*.sh）&quot;">​</a></h2><ul><li><strong>21 個 <code>.sh</code> 腳本（不含 <code>lib/common.sh</code>）全數在 settings.json 中被引用，且 <code>test -x</code> 全部 PASS</strong>（無孤兒、無死佈線）。</li><li><code>diff</code> 结果为空（wired set == actual file set 完全相等）。</li><li><code>.claude/hooks/INDEX.md</code> 宣稱「共 22 個 hook 腳本」= 21 個事件腳本 + <code>lib/common.sh</code>，數字正確。</li><li>README 宣稱「18 個 settings.json 設定群組」— <strong>實測為 17 個 matcher 群組</strong>（SessionStart 1 + UserPromptSubmit 1 + PreToolUse 4 + PostToolUseFailure 1 + PostToolUse 5 + PreCompact 1 + PostCompact 1 + Stop 1 + SessionEnd 1 + PermissionRequest 1 = 17）。<strong>輕微計數漂移（18 vs 17），非阻斷性但建議下次同步時修正</strong>（<code>.claude/hooks/INDEX.md</code> 開頭 summary 行）。</li></ul><h2 id="_3-hook-scripts-快速健檢" tabindex="-1">3. Hook scripts 快速健檢 <a class="header-anchor" href="#_3-hook-scripts-快速健檢" aria-label="Permalink to &quot;3. Hook scripts 快速健檢&quot;">​</a></h2><ul><li><strong>無寫死模型名版本</strong>（<code>grep -nE &quot;claude-(3|opus|sonnet|haiku)-[0-9]&quot;</code> 全部 hooks 無命中）。</li><li><strong>無寫死絕對路徑</strong>（<code>/Users/xxx</code> 硬編碼）；全用 <code>$CLAUDE_PROJECT_DIR</code> / <code>$HOME</code> / <code>git rev-parse --show-toplevel</code> fallback。乾淨。</li><li><strong>重型 hook（每次 UserPromptSubmit / 每次 Bash 都跑）</strong>： <ul><li><code>user-prompt-submit.sh</code>（192 行，UserPromptSubmit matcher <code>&quot;&quot;</code> = 每個 prompt 都跑，timeout 30s）：內含 <strong>3 次 <code>python3</code> subprocess spawn</strong> + 2 次 <code>git log</code>/<code>git rev-list</code> 呼叫（讀 MEMORY.md commit 距離）+ 1 次讀 cost-log。單次開銷估 100–300ms（3× python cold start + 2× git subprocess），<strong>session 長跑時累積成本最高的 hook</strong>。</li><li><code>tool-log.sh</code>（每次 Bash PostToolUse + PostToolUseFailure 都跑，async + timeout 5s）：async 執行不阻塞主線程，但仍 fork python3；因為每次 Bash 呼叫觸發，次數最多。</li><li><code>monitor-reminder.sh</code>（每次 Bash 都跑，PostToolUse，timeout 5s，非 async）：<strong>3 次 python3 subprocess</strong>（<code>echo | python3 -c</code> × 3）在同步路徑上，是目前<strong>唯一每次 Bash 都同步阻塞執行且含多重 python spawn 的 hook</strong>——若 Bash 呼叫頻繁（agentic session 常見），此 hook 為主要延遲來源候選。</li><li><code>memory-pr-record-gh.sh</code>（每次 Bash 都掛，async，timeout 90s）：async 不阻塞，但每次 Bash（非僅 <code>gh pr create</code>）都觸發一次 script 啟動判斷，屬佈線寬鬆（matcher 是 <code>Bash</code> 而非 <code>Bash(gh pr create*)</code>），建議未來收斂 matcher 範圍以減少無謂 fork。</li></ul></li></ul><h2 id="_4-commands-vs-skills-重複-readme-同步" tabindex="-1">4. Commands vs Skills 重複 + README 同步 <a class="header-anchor" href="#_4-commands-vs-skills-重複-readme-同步" aria-label="Permalink to &quot;4. Commands vs Skills 重複 + README 同步&quot;">​</a></h2><ul><li><code>.claude/commands/</code> 實際：<code>autoresearch/</code>（子目錄，10 個子命令）+ 5 個 <code>.md</code>（<code>grill</code> <code>memory-compactor</code> <code>plan</code> <code>quick-commit</code> <code>quick-pr</code>）+ <code>README.md</code>。README 表列 6 行（<code>autoresearch/</code> 算 1 項）= 與題述「7 項」（含 README 自身或算法不同）<strong>基本同步</strong>，內容與實際檔案一致，無缺漏無多餘。</li><li><code>memory-compactor</code>：commands 版是 orchestration wrapper（呼叫 agent 執行壓縮），agents 版是實際執行者——<strong>非重複，職責分工正確</strong>（見上方 §1）。</li><li><code>.claude/skills/</code> 中無獨立 <code>memory-compactor</code> skill 目錄；<code>RESOLVER.md</code>／<code>pilot-review</code>／<code>handoff</code>／<code>harness-meta</code>／<code>dreaming-consolidator</code> 僅「引用」memory-compactor 作委派對象，非重複實作。</li></ul><h2 id="_5-index-md-同步性" tabindex="-1">5. INDEX.md 同步性 <a class="header-anchor" href="#_5-index-md-同步性" aria-label="Permalink to &quot;5. INDEX.md 同步性&quot;">​</a></h2><ul><li><code>.claude/agents/INDEX.md</code>：宣稱「共 13 個 specialist agents」，實際 <code>ls .claude/agents/*.md</code>（扣除 INDEX.md 自身）= 13 檔，<strong>完全同步</strong>，速查表逐列核對用途/model/禁止欄位皆與各 agent frontmatter 一致。</li><li><code>scripts/INDEX.md</code>：宣稱「51 個自動化腳本」，<code>find scripts -type f \\( -name &quot;*.sh&quot; -o -name &quot;*.py&quot; \\)</code> 實測 = <strong>51，完全同步</strong>（<code>Updated: 2026-07-01</code>，且 <code>scripts/sync-workspace.sh</code> §13b 有自動同步機制維護此計數）。</li></ul><h2 id="綜合建議-僅供-record-非本次委派修改範圍" tabindex="-1">綜合建議（僅供 record，非本次委派修改範圍） <a class="header-anchor" href="#綜合建議-僅供-record-非本次委派修改範圍" aria-label="Permalink to &quot;綜合建議（僅供 record，非本次委派修改範圍）&quot;">​</a></h2><ol><li><code>.claude/hooks/INDEX.md</code> 開頭「18 個 settings.json 設定群組」→ 應更正為 17（1 行數字漂移）。</li><li><code>memory-pr-record-gh.sh</code> 的 PostToolUse matcher 目前綁 <code>Bash</code>（全量），可收斂為更精確 pattern 降低無謂 fork 次數。</li><li><code>monitor-reminder.sh</code> 同步執行 3 次 python3 spawn，為目前每次 Bash 呼叫的主要延遲熱點，若後續要做 hook 效能優化可從此下手（非本次任務範圍，僅記錄觀察）。</li></ol>',15)])])}const g=e(t,[["render",a]]);export{u as __pageData,g as default};
